/**
 * Cryptographic operations using the browser's native Web Crypto API.
 * PBKDF2 for key derivation (100,000 iterations, SHA-256)
 * AES-GCM 256-bit for authenticated encryption with unique 12-byte IVs.
 * ZERO external dependencies, 100% offline.
 */

const CANARY_SECRET = '__OFFLINE_VAULT_CANARY_OK__';
const PBKDF2_ITERATIONS = 100000;

// Convert Uint8Array to base64 string
export function bufferToBase64(buffer) {
  let binary = '';
  const bytes = new Uint8Array(buffer);
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return window.btoa(binary);
}

// Convert base64 string to Uint8Array
export function base64ToBuffer(base64) {
  const binary = window.atob(base64);
  const len = binary.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

// Generate cryptographically secure random salt (default 16 bytes)
export function generateSalt(length = 16) {
  const salt = new Uint8Array(length);
  window.crypto.getRandomValues(salt);
  return bufferToBase64(salt);
}

// Generate random IV (12 bytes recommended for AES-GCM)
export function generateIV() {
  const iv = new Uint8Array(12);
  window.crypto.getRandomValues(iv);
  return iv;
}

/**
 * Derive an AES-GCM 256-bit CryptoKey from a master password and salt using PBKDF2.
 */
export async function deriveMasterKey(masterPassword, saltBase64) {
  const encoder = new TextEncoder();
  const passwordKey = await window.crypto.subtle.importKey(
    'raw',
    encoder.encode(masterPassword),
    { name: 'PBKDF2' },
    false,
    ['deriveKey']
  );

  const salt = base64ToBuffer(saltBase64);

  const aesKey = await window.crypto.subtle.deriveKey(
    {
      name: 'PBKDF2',
      salt,
      iterations: PBKDF2_ITERATIONS,
      hash: 'SHA-256'
    },
    passwordKey,
    {
      name: 'AES-GCM',
      length: 256
    },
    false,
    ['encrypt', 'decrypt']
  );

  return aesKey;
}

/**
 * Encrypt any serializable data using AES-GCM and a derived CryptoKey.
 * Returns an object with base64 encoded ciphertext and iv.
 */
export async function encryptPayload(data, key) {
  const encoder = new TextEncoder();
  const encodedData = encoder.encode(JSON.stringify(data));
  const iv = generateIV();

  const encryptedBuffer = await window.crypto.subtle.encrypt(
    {
      name: 'AES-GCM',
      iv
    },
    key,
    encodedData
  );

  return {
    ciphertext: bufferToBase64(encryptedBuffer),
    iv: bufferToBase64(iv)
  };
}

/**
 * Decrypt ciphertext using AES-GCM and a derived CryptoKey.
 * Throws an error if decryption fails (e.g. incorrect key / tampered data).
 */
export async function decryptPayload(encryptedObj, key) {
  const { ciphertext, iv } = encryptedObj;
  const ivBuffer = base64ToBuffer(iv);
  const dataBuffer = base64ToBuffer(ciphertext);

  const decryptedBuffer = await window.crypto.subtle.decrypt(
    {
      name: 'AES-GCM',
      iv: ivBuffer
    },
    key,
    dataBuffer
  );

  const decoder = new TextDecoder();
  const jsonString = decoder.decode(decryptedBuffer);
  return JSON.parse(jsonString);
}

/**
 * Creates the auth verification token (canary) to safely test passwords without storing them.
 */
export async function createAuthVerification(key) {
  return await encryptPayload({ canary: CANARY_SECRET }, key);
}

/**
 * Verifies if a derived key is valid by attempting to decrypt the canary.
 */
export async function verifyAuth(encryptedCanary, key) {
  try {
    const result = await decryptPayload(encryptedCanary, key);
    return result && result.canary === CANARY_SECRET;
  } catch (err) {
    return false;
  }
}

/**
 * Native IndexedDB service for local offline storage.
 * Zero external dependencies, pure browser storage API.
 */

const DB_NAME = 'OfflinePasswordManagerDB';
const DB_VERSION = 1;

let dbPromise = null;

export function openDatabase() {
  if (dbPromise) return dbPromise;

  dbPromise = new Promise((resolve, reject) => {
    const request = window.indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains('meta')) {
        db.createObjectStore('meta', { keyPath: 'id' });
      }
      if (!db.objectStoreNames.contains('items')) {
        const itemStore = db.createObjectStore('items', { keyPath: 'id' });
        itemStore.createIndex('category', 'category', { unique: false });
        itemStore.createIndex('favorite', 'favorite', { unique: false });
        itemStore.createIndex('updatedAt', 'updatedAt', { unique: false });
      }
    };

    request.onsuccess = (event) => {
      resolve(event.target.result);
    };

    request.onerror = (event) => {
      reject(new Error(`IndexedDB open error: ${event.target.error?.message}`));
    };
  });

  return dbPromise;
}

export async function getMeta() {
  const db = await openDatabase();
  return new Promise((resolve, reject) => {
    const tx = db.transaction('meta', 'readonly');
    const store = tx.objectStore('meta');
    const request = store.get('auth');

    request.onsuccess = () => resolve(request.result || null);
    request.onerror = () => reject(request.error);
  });
}

export async function saveMeta(metaData) {
  const db = await openDatabase();
  return new Promise((resolve, reject) => {
    const tx = db.transaction('meta', 'readwrite');
    const store = tx.objectStore('meta');
    const request = store.put({ id: 'auth', ...metaData, updatedAt: new Date().toISOString() });

    request.onsuccess = () => resolve(true);
    request.onerror = () => reject(request.error);
  });
}

export async function getAllEncryptedItems() {
  const db = await openDatabase();
  return new Promise((resolve, reject) => {
    const tx = db.transaction('items', 'readonly');
    const store = tx.objectStore('items');
    const request = store.getAll();

    request.onsuccess = () => resolve(request.result || []);
    request.onerror = () => reject(request.error);
  });
}

export async function saveEncryptedItem(item) {
  const db = await openDatabase();
  return new Promise((resolve, reject) => {
    const tx = db.transaction('items', 'readwrite');
    const store = tx.objectStore('items');
    const request = store.put({
      ...item,
      updatedAt: new Date().toISOString()
    });

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

export async function deleteEncryptedItem(id) {
  const db = await openDatabase();
  return new Promise((resolve, reject) => {
    const tx = db.transaction('items', 'readwrite');
    const store = tx.objectStore('items');
    const request = store.delete(id);

    request.onsuccess = () => resolve(true);
    request.onerror = () => reject(request.error);
  });
}

export async function clearAllData() {
  const db = await openDatabase();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(['meta', 'items'], 'readwrite');
    tx.objectStore('meta').clear();
    tx.objectStore('items').clear();

    tx.oncomplete = () => resolve(true);
    tx.onerror = () => reject(tx.error);
  });
}

/**
 * Cryptographically secure password generation and strength estimation.
 */

const LOWERCASE = 'abcdefghijklmnopqrstuvwxyz';
const UPPERCASE = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
const NUMBERS = '0123456789';
const SYMBOLS = '!@#$%^&*()_+-=[]{}|;:,.<>?';
const AMBIGUOUS = /[il1Lo0O]/g;

// Secure random integer in range [0, max - 1]
function getSecureRandomInt(max) {
  const array = new Uint32Array(1);
  const maxRange = Math.floor(0xffffffff / max) * max;
  let rand;
  do {
    window.crypto.getRandomValues(array);
    rand = array[0];
  } while (rand >= maxRange);
  return rand % max;
}

export function generateSecurePassword({
  length = 18,
  useLower = true,
  useUpper = true,
  useNumbers = true,
  useSymbols = true,
  avoidAmbiguous = false
} = {}) {
  let charPool = '';
  let guaranteedChars = [];

  let lower = LOWERCASE;
  let upper = UPPERCASE;
  let nums = NUMBERS;
  let syms = SYMBOLS;

  if (avoidAmbiguous) {
    lower = lower.replace(AMBIGUOUS, '');
    upper = upper.replace(AMBIGUOUS, '');
    nums = nums.replace(AMBIGUOUS, '');
    syms = syms.replace(/[{}[\]()/\\'"`~,;:.<>]/g, '');
  }

  if (useLower) {
    charPool += lower;
    guaranteedChars.push(lower[getSecureRandomInt(lower.length)]);
  }
  if (useUpper) {
    charPool += upper;
    guaranteedChars.push(upper[getSecureRandomInt(upper.length)]);
  }
  if (useNumbers) {
    charPool += nums;
    guaranteedChars.push(nums[getSecureRandomInt(nums.length)]);
  }
  if (useSymbols) {
    charPool += syms;
    guaranteedChars.push(syms[getSecureRandomInt(syms.length)]);
  }

  if (charPool.length === 0) {
    charPool = lower;
    guaranteedChars.push(lower[getSecureRandomInt(lower.length)]);
  }

  const resultChars = [...guaranteedChars];
  while (resultChars.length < length) {
    resultChars.push(charPool[getSecureRandomInt(charPool.length)]);
  }

  // Fisher-Yates shuffle with cryptographic random values
  for (let i = resultChars.length - 1; i > 0; i--) {
    const j = getSecureRandomInt(i + 1);
    [resultChars[i], resultChars[j]] = [resultChars[j], resultChars[i]];
  }

  return resultChars.join('');
}

export function evaluatePasswordStrength(password) {
  if (!password) {
    return { score: 0, label: 'Empty', color: 'var(--text-muted)', bits: 0 };
  }

  let poolSize = 0;
  if (/[a-z]/.test(password)) poolSize += 26;
  if (/[A-Z]/.test(password)) poolSize += 26;
  if (/[0-9]/.test(password)) poolSize += 10;
  if (/[^a-zA-Z0-9]/.test(password)) poolSize += 32;

  const bits = Math.floor(password.length * (Math.log2(poolSize || 1)));

  if (password.length < 8 || bits < 40) {
    return { score: 1, label: 'Weak', color: 'var(--danger)', bits };
  } else if (password.length < 12 || bits < 60) {
    return { score: 2, label: 'Fair', color: 'var(--warning)', bits };
  } else if (password.length < 16 || bits < 80) {
    return { score: 3, label: 'Strong', color: 'var(--primary)', bits };
  } else {
    return { score: 4, label: 'Very Strong', color: '#34d399', bits };
  }
}

import React, { createContext, useContext, useState, useCallback } from 'react';
import { Check, AlertTriangle, X } from './Icons';

const ToastContext = createContext(null);

export function ToastProvider({ children }) {
  const [toasts, setToasts] = useState([]);

  const addToast = useCallback((message, type = 'success', duration = 2500) => {
    const id = Date.now() + Math.random().toString(36).substr(2, 4);
    setToasts((prev) => [...prev, { id, message, type }]);

    if (duration > 0) {
      setTimeout(() => {
        setToasts((prev) => prev.filter((t) => t.id !== id));
      }, duration);
    }
  }, []);

  const removeToast = useCallback((id) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  }, []);

  return (
    <ToastContext.Provider value={{ showToast: addToast }}>
      {children}
      <div className="toast-container" role="region" aria-live="polite">
        {toasts.map((toast) => (
          <div key={toast.id} className={`toast toast-${toast.type}`}>
            {toast.type === 'success' ? (
              <span style={{ color: 'var(--primary)' }}><Check size={18} /></span>
            ) : (
              <span style={{ color: 'var(--danger)' }}><AlertTriangle size={18} /></span>
            )}
            <span style={{ flex: 1 }}>{toast.message}</span>
            <button
              onClick={() => removeToast(toast.id)}
              className="btn-icon"
              style={{ padding: '2px', color: 'var(--text-muted)' }}
            >
              <X size={14} />
            </button>
          </div>
        ))}
      </div>
    </ToastContext.Provider>
  );
}

export function useToast() {
  const context = useContext(ToastContext);
  if (!context) {
    throw new Error('useToast must be used within a ToastProvider');
  }
  return context;
}

import React, { createContext, useContext, useState, useEffect, useRef, useCallback } from 'react';
import {
  generateSalt,
  deriveMasterKey,
  createAuthVerification,
  verifyAuth,
  encryptPayload,
  decryptPayload
} from '../services/crypto';
import {
  getMeta,
  saveMeta,
  getAllEncryptedItems,
  saveEncryptedItem,
  deleteEncryptedItem,
  clearAllData
} from '../services/db';

const VaultContext = createContext(null);

export function VaultProvider({ children }) {
  const [vaultState, setVaultState] = useState('loading'); // 'loading' | 'uninitialized' | 'locked' | 'unlocked'
  const [items, setItems] = useState([]);
  const [autoLockMinutes, setAutoLockMinutes] = useState(15);
  const [metaInfo, setMetaInfo] = useState(null);

  // In-memory master key (never stored to disk or localStorage)
  const masterKeyRef = useRef(null);
  const lastActiveRef = useRef(Date.now());

  // Check vault initialization on load
  const checkVaultStatus = useCallback(async () => {
    try {
      const meta = await getMeta();
      if (!meta || !meta.salt || !meta.canary) {
        setVaultState('uninitialized');
      } else {
        setMetaInfo(meta);
        if (meta.autoLockMinutes) {
          setAutoLockMinutes(meta.autoLockMinutes);
        }
        setVaultState('locked');
      }
    } catch (err) {
      console.error('Error initializing vault:', err);
      setVaultState('uninitialized');
    }
  }, []);

  useEffect(() => {
    checkVaultStatus();
  }, [checkVaultStatus]);

  // Lock Vault: Immediately clear sensitive keys and decrypted items from memory
  const lockVault = useCallback(() => {
    masterKeyRef.current = null;
    setItems([]);
    setVaultState('locked');
  }, []);

  // Setup Vault (first-time initialization)
  const setupVault = async (masterPassword) => {
    const salt = generateSalt(16);
    const key = await deriveMasterKey(masterPassword, salt);
    const canary = await createAuthVerification(key);

    const meta = {
      salt,
      canary,
      autoLockMinutes: 15,
      createdAt: new Date().toISOString()
    };

    await saveMeta(meta);
    setMetaInfo(meta);
    masterKeyRef.current = key;
    setItems([]);
    setVaultState('unlocked');
    lastActiveRef.current = Date.now();
  };

  // Unlock Vault
  const unlockVault = async (masterPassword) => {
    const meta = await getMeta();
    if (!meta || !meta.salt || !meta.canary) {
      throw new Error('Vault is not initialized.');
    }

    const key = await deriveMasterKey(masterPassword, meta.salt);
    const isValid = await verifyAuth(meta.canary, key);
    if (!isValid) {
      throw new Error('Incorrect master password.');
    }

    // Load and decrypt items
    const encryptedItems = await getAllEncryptedItems();
    const decryptedItems = [];

    for (const item of encryptedItems) {
      try {
        const payload = await decryptPayload(
          { ciphertext: item.ciphertext, iv: item.iv },
          key
        );
        decryptedItems.push({
          id: item.id,
          category: item.category || 'logins',
          favorite: !!item.favorite,
          updatedAt: item.updatedAt,
          createdAt: item.createdAt,
          ...payload
        });
      } catch (err) {
        console.error(`Failed to decrypt item ${item.id}`, err);
      }
    }

    masterKeyRef.current = key;
    setItems(decryptedItems);
    setMetaInfo(meta);
    if (meta.autoLockMinutes) {
      setAutoLockMinutes(meta.autoLockMinutes);
    }
    setVaultState('unlocked');
    lastActiveRef.current = Date.now();
  };

  // Add Item
  const addItem = async (itemData) => {
    if (!masterKeyRef.current) throw new Error('Vault is locked');

    const id = Date.now().toString(36) + Math.random().toString(36).substr(2, 6);
    const now = new Date().toISOString();

    const { category = 'logins', favorite = false, ...secretData } = itemData;

    const encrypted = await encryptPayload(secretData, masterKeyRef.current);

    const record = {
      id,
      category,
      favorite,
      ciphertext: encrypted.ciphertext,
      iv: encrypted.iv,
      createdAt: now,
      updatedAt: now
    };

    await saveEncryptedItem(record);

    const newItem = {
      id,
      category,
      favorite,
      createdAt: now,
      updatedAt: now,
      ...secretData
    };

    setItems((prev) => [newItem, ...prev]);
    lastActiveRef.current = Date.now();
    return newItem;
  };

  // Update Item
  const updateItem = async (id, itemData) => {
    if (!masterKeyRef.current) throw new Error('Vault is locked');

    const existing = items.find((i) => i.id === id);
    if (!existing) throw new Error('Item not found');

    const { category = existing.category, favorite = existing.favorite, ...secretData } = itemData;

    const encrypted = await encryptPayload(secretData, masterKeyRef.current);
    const now = new Date().toISOString();

    const record = {
      id,
      category,
      favorite,
      ciphertext: encrypted.ciphertext,
      iv: encrypted.iv,
      createdAt: existing.createdAt || now,
      updatedAt: now
    };

    await saveEncryptedItem(record);

    const updated = {
      ...existing,
      category,
      favorite,
      updatedAt: now,
      ...secretData
    };

    setItems((prev) => prev.map((item) => (item.id === id ? updated : item)));
    lastActiveRef.current = Date.now();
    return updated;
  };

  // Delete Item
  const deleteItem = async (id) => {
    await deleteEncryptedItem(id);
    setItems((prev) => prev.filter((i) => i.id !== id));
    lastActiveRef.current = Date.now();
  };

  // Toggle Favorite
  const toggleFavorite = async (id) => {
    const item = items.find((i) => i.id === id);
    if (!item) return;
    await updateItem(id, { ...item, favorite: !item.favorite });
  };

  // Change Master Password (re-encrypts everything)
  const changeMasterPassword = async (currentPassword, newPassword) => {
    if (!metaInfo) throw new Error('Vault metadata not found');

    // 1. Verify current password
    const oldKey = await deriveMasterKey(currentPassword, metaInfo.salt);
    const isValid = await verifyAuth(metaInfo.canary, oldKey);
    if (!isValid) {
      throw new Error('Current master password does not match.');
    }

    // 2. Generate new salt and derive new key
    const newSalt = generateSalt(16);
    const newKey = await deriveMasterKey(newPassword, newSalt);
    const newCanary = await createAuthVerification(newKey);

    // 3. Re-encrypt all items
    for (const item of items) {
      const { id, category, favorite, createdAt, updatedAt, ...secretData } = item;
      const encrypted = await encryptPayload(secretData, newKey);
      await saveEncryptedItem({
        id,
        category,
        favorite,
        ciphertext: encrypted.ciphertext,
        iv: encrypted.iv,
        createdAt,
        updatedAt: new Date().toISOString()
      });
    }

    // 4. Save new meta
    const updatedMeta = {
      ...metaInfo,
      salt: newSalt,
      canary: newCanary,
      updatedAt: new Date().toISOString()
    };
    await saveMeta(updatedMeta);

    masterKeyRef.current = newKey;
    setMetaInfo(updatedMeta);
    lastActiveRef.current = Date.now();
  };

  // Update Settings (Auto-lock timer)
  const updateSettings = async (settings) => {
    if (settings.autoLockMinutes !== undefined) {
      setAutoLockMinutes(settings.autoLockMinutes);
      if (metaInfo) {
        const updatedMeta = { ...metaInfo, autoLockMinutes: settings.autoLockMinutes };
        await saveMeta(updatedMeta);
        setMetaInfo(updatedMeta);
      }
    }
  };

  // Export Encrypted Vault Backup
  const exportEncryptedVault = async () => {
    const meta = await getMeta();
    const encryptedRecords = await getAllEncryptedItems();

    const backupPayload = {
      appName: 'OfflinePasswordManager',
      version: 1,
      exportedAt: new Date().toISOString(),
      salt: meta.salt,
      canary: meta.canary,
      items: encryptedRecords
    };

    const blob = new Blob([JSON.stringify(backupPayload, null, 2)], {
      type: 'application/json'
    });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `offline-vault-backup-${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  // Import Backup
  const importBackup = async (backupJsonString, backupMasterPassword) => {
    let backup;
    try {
      backup = JSON.parse(backupJsonString);
    } catch (e) {
      throw new Error('Invalid JSON backup file.');
    }

    if (!backup.salt || !backup.canary || !Array.isArray(backup.items)) {
      throw new Error('Unrecognized backup format.');
    }

    // Verify password for the backup
    const backupKey = await deriveMasterKey(backupMasterPassword, backup.salt);
    const isValid = await verifyAuth(backup.canary, backupKey);
    if (!isValid) {
      throw new Error('Incorrect master password for the backup file.');
    }

    let importCount = 0;
    // Decrypt items from backup and re-encrypt into current vault
    for (const bItem of backup.items) {
      try {
        const secretData = await decryptPayload(
          { ciphertext: bItem.ciphertext, iv: bItem.iv },
          backupKey
        );
        await addItem({
          category: bItem.category || 'logins',
          favorite: !!bItem.favorite,
          ...secretData
        });
        importCount++;
      } catch (err) {
        console.error('Failed to import item', err);
      }
    }

    return importCount;
  };

  // Reset / Clear Vault
  const resetVault = async () => {
    await clearAllData();
    masterKeyRef.current = null;
    setItems([]);
    setMetaInfo(null);
    setVaultState('uninitialized');
  };

  // Auto-lock inactivity detection
  useEffect(() => {
    if (vaultState !== 'unlocked' || autoLockMinutes <= 0) return;

    const resetActivity = () => {
      lastActiveRef.current = Date.now();
    };

    const events = ['mousemove', 'mousedown', 'keydown', 'touchstart', 'scroll'];
    events.forEach((evt) => window.addEventListener(evt, resetActivity));

    const checkInterval = setInterval(() => {
      const idleTime = Date.now() - lastActiveRef.current;
      if (idleTime >= autoLockMinutes * 60 * 1000) {
        lockVault();
      }
    }, 10000);

    return () => {
      events.forEach((evt) => window.removeEventListener(evt, resetActivity));
      clearInterval(checkInterval);
    };
  }, [vaultState, autoLockMinutes, lockVault]);

  return (
    <VaultContext.Provider
      value={{
        vaultState,
        items,
        autoLockMinutes,
        setupVault,
        unlockVault,
        lockVault,
        addItem,
        updateItem,
        deleteItem,
        toggleFavorite,
        changeMasterPassword,
        updateSettings,
        exportEncryptedVault,
        importBackup,
        resetVault
      }}
    >
      {children}
    </VaultContext.Provider>
  );
}

export function useVault() {
  const context = useContext(VaultContext);
  if (!context) {
    throw new Error('useVault must be used within a VaultProvider');
  }
  return context;
}

import React, { useState } from 'react';
import { useVault } from '../context/VaultContext';
import { useToast } from './Toast';
import { Shield, Lock, Unlock, Eye, EyeOff, Key, AlertTriangle } from './Icons';
import { evaluatePasswordStrength } from '../services/generator';

export function UnlockScreen() {
  const { vaultState, setupVault, unlockVault } = useVault();
  const { showToast } = useToast();

  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [shake, setShake] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');

  const isSetup = vaultState === 'uninitialized';
  const strength = isSetup ? evaluatePasswordStrength(password) : null;

  const triggerShake = (msg) => {
    setErrorMsg(msg);
    setShake(true);
    setTimeout(() => setShake(false), 500);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setErrorMsg('');

    if (!password) {
      triggerShake('Please enter your master password.');
      return;
    }

    if (isSetup) {
      if (password.length < 8) {
        triggerShake('Master password should be at least 8 characters long.');
        return;
      }
      if (password !== confirmPassword) {
        triggerShake('Passwords do not match.');
        return;
      }

      setIsLoading(true);
      try {
        await setupVault(password);
        showToast('Vault created successfully!');
      } catch (err) {
        triggerShake('Failed to create vault: ' + err.message);
      } finally {
        setIsLoading(false);
      }
    } else {
      setIsLoading(true);
      try {
        await unlockVault(password);
        showToast('Vault unlocked.');
      } catch (err) {
        triggerShake('Incorrect master password. Please try again.');
      } finally {
        setIsLoading(false);
      }
    }
  };

  return (
    <div className="lock-screen-wrapper">
      <div className={`lock-card ${shake ? 'shake' : ''}`}>
        <div className="lock-logo-badge">
          {isSetup ? <Key size={32} /> : <Lock size={32} />}
        </div>

        <div>
          <h1 style={{ fontSize: '1.5rem', fontWeight: 700, marginBottom: '0.35rem' }}>
            {isSetup ? 'Create Your Vault' : 'Vault Locked'}
          </h1>
          <p style={{ color: 'var(--text-secondary)', fontSize: '0.9rem' }}>
            {isSetup
              ? 'Set a master password to encrypt your credentials locally.'
              : 'Enter your master password to unlock your offline vault.'}
          </p>
        </div>

        {errorMsg && (
          <div
            style={{
              padding: '0.65rem 0.85rem',
              borderRadius: 'var(--radius-md)',
              background: 'var(--danger-light)',
              color: 'var(--danger)',
              fontSize: '0.85rem',
              display: 'flex',
              alignItems: 'center',
              gap: '0.5rem',
              textAlign: 'left'
            }}
          >
            <AlertTriangle size={18} style={{ flexShrink: 0 }} />
            <span>{errorMsg}</span>
          </div>
        )}

        <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '1rem', textAlign: 'left' }}>
          <div className="form-group">
            <label className="form-label">Master Password</label>
            <div className="input-with-action">
              <input
                type={showPassword ? 'text' : 'password'}
                className="form-input"
                placeholder="Enter master password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                autoFocus
                disabled={isLoading}
              />
              <div className="input-action-buttons">
                <button
                  type="button"
                  className="btn-icon"
                  onClick={() => setShowPassword(!showPassword)}
                  title={showPassword ? 'Hide password' : 'Show password'}
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>

            {isSetup && password && (
              <div style={{ marginTop: '0.35rem' }}>
                <div className="strength-meter">
                  <div className={`strength-bar ${strength.score >= 1 ? (strength.score === 1 ? 'weak' : strength.score === 2 ? 'medium' : 'strong') : ''}`} />
                  <div className={`strength-bar ${strength.score >= 2 ? (strength.score === 2 ? 'medium' : 'strong') : ''}`} />
                  <div className={`strength-bar ${strength.score >= 3 ? 'strong' : ''}`} />
                  <div className={`strength-bar ${strength.score >= 4 ? 'strong' : ''}`} />
                </div>
                <div className="strength-text" style={{ color: strength.color }}>
                  Strength: {strength.label} ({strength.bits} bits entropy)
                </div>
              </div>
            )}
          </div>

          {isSetup && (
            <div className="form-group">
              <label className="form-label">Confirm Master Password</label>
              <input
                type={showPassword ? 'text' : 'password'}
                className="form-input"
                placeholder="Repeat master password"
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                disabled={isLoading}
              />
            </div>
          )}

          <button
            type="submit"
            className="btn btn-primary"
            style={{ width: '100%', padding: '0.75rem', marginTop: '0.5rem' }}
            disabled={isLoading}
          >
            {isLoading ? (
              <span>Decrypting...</span>
            ) : isSetup ? (
              <>
                <Shield size={18} /> Create Secure Vault
              </>
            ) : (
              <>
                <Unlock size={18} /> Unlock Vault
              </>
            )}
          </button>
        </form>

        <div
          style={{
            background: 'rgba(16, 185, 129, 0.08)',
            border: '1px solid rgba(16, 185, 129, 0.2)',
            borderRadius: 'var(--radius-md)',
            padding: '0.85rem',
            fontSize: '0.8rem',
            color: 'var(--text-secondary)',
            textAlign: 'left'
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', color: 'var(--primary)', fontWeight: 600, marginBottom: '0.25rem' }}>
            <Shield size={16} /> 100% Offline & Zero-Knowledge
          </div>
          <p>
            Your data is encrypted with AES-GCM 256-bit and saved exclusively in your browser's IndexedDB. No backend servers, no cloud sync, zero telemetry.
          </p>
        </div>
      </div>
    </div>
  );
}

